type ChartProps={compact?:boolean;visible?:string[];data?:OrgReportData['chartData']}
function ImpactCharts({compact=false,visible=['beneficiaries','activities','funds'],data}:ChartProps) {
  return <div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,340px),1fr))'}}>
    {visible.includes('beneficiaries')&&<div className="card chart-card" style={compact?{padding:14}:undefined}><h3 className="chart-title">Beneficiaries reached over time</h3><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><LineChart data={data?data.months:months} margin={{top:8,right:12,left:-18,bottom:0}}><CartesianGrid stroke="var(--border)" strokeDasharray="3 3"/><XAxis dataKey="month" tick={{fontSize:11}}/><YAxis tick={{fontSize:11}}/><Tooltip/><Legend/><Line type="monotone" dataKey="beneficiaries" name="People reached" stroke="var(--primary)" strokeWidth={2.5} dot={false} isAnimationActive={true}/></LineChart></ResponsiveContainer></div></div>}
    {visible.includes('activities')&&<div className="card chart-card" style={compact?{padding:14}:undefined}><h3 className="chart-title">Activities by programme</h3><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={data?data.programs:programData} margin={{top:8,right:12,left:-18,bottom:0}}><CartesianGrid stroke="var(--border)" strokeDasharray="3 3"/><XAxis dataKey="program" tick={{fontSize:11}}/><YAxis tick={{fontSize:11}}/><Tooltip/><Legend/><Bar dataKey="activities" name="Activities" fill="var(--primary)" radius={[4,4,0,0]} isAnimationActive={true}/></BarChart></ResponsiveContainer></div></div>}
    {visible.includes('funds')&&<div className="card chart-card" style={compact?{padding:14}:undefined}><h3 className="chart-title">Funds by category</h3><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={data?data.funds:fundsData} margin={{top:8,right:12,left:-6,bottom:0}}><CartesianGrid stroke="var(--border)" strokeDasharray="3 3"/><XAxis dataKey="category" tick={{fontSize:11}}/><YAxis tick={{fontSize:11}}/><Tooltip formatter={(value) => currency(Number(value))}/><Legend/><Bar dataKey="amount" name="KES" fill="var(--green)" radius={[4,4,0,0]} isAnimationActive={true}/></BarChart></ResponsiveContainer></div></div>}
  </div>
}
function downloadPdf(title='Barnabas Impact sample report',report?:{summary:OrgReportData['summary']}) { const pdf = new jsPDF(); const summary=report?.summary; pdf.setFont('helvetica','bold');pdf.setFontSize(20);pdf.text(title,18,22);pdf.setFont('helvetica','normal');pdf.setFontSize(11);pdf.text('A practical summary of recorded programme information.',18,34);pdf.text(`Beneficiary records: ${new Intl.NumberFormat('en-KE').format(summary?.totalBeneficiaries??5420)}`,18,48);pdf.text(`Activities logged: ${new Intl.NumberFormat('en-KE').format(summary?.activities??54)}`,18,57);pdf.text(`Funds deployed: ${currency(summary?.fundsDeployed??1780000)}`,18,66);pdf.text(`Active volunteers: ${new Intl.NumberFormat('en-KE').format(summary?.activeVolunteers??32)}`,18,75);pdf.text('Barnabas Impact is a recording and reporting tool. It is not an auditor and does not provide assurance opinions.',18,91,{maxWidth:174});pdf.save('barnabas-impact-report.pdf') }
function Header() {
 const [menu,setMenu]=useState(false)
 return <header style={{background:'white',borderBottom:'1px solid var(--border)',position:'relative',zIndex:10}}><div className="container nav"><Link href="/" className="brand"><span className="brand-mark"><BarChart3 size={21}/></span><span>Barnabas Impact</span></Link><nav className="nav-links" aria-label="Main navigation"><Link href="/product">Product</Link><Link href="/sample">Sample report</Link><Link href="/pricing">Pricing</Link><Link href="/about">About</Link><Link className="btn small" href="/login">Sign in</Link></nav><button className="menu-toggle" aria-label={menu?'Close menu':'Open menu'} onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button></div>{menu&&<nav className="mobile-nav" aria-label="Mobile navigation"><Link href="/product">Product</Link><Link href="/sample">Sample report</Link><Link href="/pricing">Pricing</Link><Link href="/about">About</Link><Link href="/login">Sign in</Link><Link href="/register">Start free board</Link></nav>}</header>
}
function Footer(){return <footer className="footer"><div className="container"><div className="footer-grid"><div><Link href="/" className="brand"><span className="brand-mark"><BarChart3 size={20}/></span>Barnabas Impact</Link><p className="muted" style={{maxWidth:310,fontSize:'.88rem'}}>Show the work. Earn the trust. Practical impact reporting for community programmes across Kenya.</p></div><div><h4>Explore</h4><div className="footer-links"><Link href="/product">Product</Link><Link href="/sample">Sample public page</Link><Link href="/pricing">Pricing</Link><Link href="/about">About us</Link></div></div><div><h4>Your board</h4><div className="footer-links"><Link href="/register">Start free</Link><Link href="/login">Sign in</Link><Link href="/dashboard/reports">Reports</Link></div></div><div><h4>Reach us</h4><div className="footer-links"><a href="https://wa.me/254112272061">WhatsApp support</a><a href="https://instagram.com" target="_blank" rel="noreferrer">Instagram</a><a href="https://linkedin.com" target="_blank" rel="noreferrer">LinkedIn</a></div></div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} Barnabas Impact. Made for clear, careful reporting.</span><div style={{display:'flex',gap:16,flexWrap:'wrap'}}><Link href="/legal/privacy-policy">Privacy</Link><Link href="/legal/terms">Terms</Link><Link href="/legal/cookie-policy">Cookies</Link><button type="button" onClick={()=>window.dispatchEvent(new Event('barnabas-open-cookie-settings'))} style={{border:0,background:'transparent',color:'inherit',padding:0,cursor:'pointer'}}>Cookie preferences</button></div></div></div></footer>}
function KPI({label,value,icon:Icon}:{label:string;value:string;icon:typeof Users}){return <div className="kpi"><div style={{display:'flex',justifyContent:'space-between',gap:8,alignItems:'center'}}><span className="kpi-label">{label}</span><Icon size={18} color="var(--primary)"/></div><div className="kpi-value">{value}</div></div>}
function HomePage(){return <><section className="hero"><div className="container hero-grid"><motion.div className="hero-copy" initial={{opacity:0,y:18}} animate={{opacity:1,y:0}} transition={{duration:1}}><span className="eyebrow">Clear reports for community work</span><h1>Impact reports your donors will actually read</h1><p>Log beneficiaries, activities, and funds in one calm workspace. Then publish a clean public page and a PDF that helps your team show what changed.</p><div className="hero-actions"><Link className="btn" href="/register">Start free board <ArrowRight size={18}/></Link><Link className="btn secondary" href="/sample">See sample public page</Link></div><p style={{fontSize:'.78rem',marginTop:15}}>No card needed. Start with a free board for one project.</p></motion.div><div className="hero-panel"><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}><div><span className="eyebrow">Your impact at a glance</span><h2 style={{fontSize:'1.2rem',margin:'4px 0'}}>Community progress</h2></div><span className="pill"><Check size={14}/> In progress</span></div><div className="kpi-grid" style={{marginBottom:17}}><div className="kpi"><span className="kpi-label">People reached</span><div className="kpi-value">5,420</div></div><div className="kpi"><span className="kpi-label">Activities logged</span><div className="kpi-value">54</div></div></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><LineChart data={months.slice(0,7)} margin={{top:8,right:8,left:-26,bottom:0}}><CartesianGrid stroke="var(--border)" strokeDasharray="3 3"/><XAxis dataKey="month" tick={{fontSize:11}}/><YAxis tick={{fontSize:11}}/><Tooltip/><Legend/><Line dataKey="beneficiaries" name="People reached" stroke="var(--primary)" strokeWidth={2.5} dot={false} isAnimationActive={true}/></LineChart></ResponsiveContainer></div><div style={{fontSize:'.74rem',color:'var(--muted)',marginTop:8}}>Example figures, replace them with your own recorded work.</div></div></div></section><div className="container"><div className="trust-row">{[{I:LockKeyhole,t:'Role-aware access'},{I:ShieldCheck,t:'KDPA-aware design'},{I:ArrowDownToLine,t:'PDF export'},{I:FileText,t:'Public share link'}].map(({I,t})=><div className="trust-item" key={t}><I size={18} color="var(--primary-dark)"/>{t}</div>)}</div></div><section className="section"><div className="container"><span className="eyebrow">Simple tools, connected</span><h2 className="heading" style={{fontSize:'clamp(2rem,4vw,3rem)',maxWidth:720}}>A more useful view of the work already happening</h2><p className="muted" style={{maxWidth:680,marginBottom:28}}>Record a little as you go. Give your team a shared place to keep programme details, and build reports without chasing five different spreadsheets.</p><div className="grid module-grid">{modules.map((m,i)=><motion.article className="card module" key={m.title} initial={{opacity:0,y:18}} whileInView={{opacity:1,y:0}} viewport={{once:true,amount:.15}} transition={{delay:i*.055,duration:.35}}><div className="iconbox"><m.icon size={21}/></div><h3 style={{margin:'16px 0 7px'}}>{m.title}</h3><p className="muted" style={{margin:0,fontSize:'.91rem'}}>{m.description}</p></motion.article>)}</div></div></section><section className="section section-soft"><div className="container"><div style={{display:'flex',flexWrap:'wrap',justifyContent:'space-between',alignItems:'end',gap:20,marginBottom:24}}><div><span className="eyebrow">A clear sample, not a promise</span><h2 className="heading" style={{fontSize:'clamp(2rem,4vw,3rem)',marginBottom:0}}>Small details add up</h2></div><Link className="btn secondary" href="/sample">Explore sample report <ArrowRight size={17}/></Link></div><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,220px),1fr))'}}><KPI label="Beneficiaries reached" value="5,420" icon={Users}/><KPI label="Counties" value="4" icon={Landmark}/><KPI label="Activities logged" value="54" icon={Activity}/><KPI label="Funds deployed" value="KES 1.78m" icon={CircleDollarSign}/></div><p className="muted" style={{fontSize:'.78rem',margin:'12px 0 0'}}>Static demonstration figures for illustration only.</p></div></section><section className="section"><div className="container"><div style={{textAlign:'center',maxWidth:700,margin:'0 auto 30px'}}><span className="eyebrow">Keep the reporting rhythm</span><h2 className="heading" style={{fontSize:'clamp(2rem,4vw,3rem)'}}>Three steps from field notes to a clear report</h2></div><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,250px),1fr))'}}>{[['01','Create your organisation board','Set up your programme, invite your team, and choose the information you need to keep.'],['02','Log work each week','Add beneficiary records, activities, finance notes, and useful evidence as the work happens.'],['03','Publish and export','Share a clear public page when you are ready, then download a PDF for your next update.']].map(([n,t,d])=><article className="card step-card" key={n}><div className="step-number">{n}</div><h3>{t}</h3><p className="muted" style={{margin:0}}>{d}</p></article>)}</div></div></section><section className="section section-soft"><div className="container"><div style={{textAlign:'center',marginBottom:28}}><span className="eyebrow">Made for practical reporting</span><h2 className="heading" style={{fontSize:'clamp(2rem,4vw,3rem)'}}>Built around the people doing the work</h2></div><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,270px),1fr))'}}>{[['“I can finally pull our monthly figures together without reopening every notebook.”','Amina W.','NGO programme coordinator',images.portrait1],['“Our board understands what we are doing because the update is short and clear.”','Peter K.','NGO programme coordinator',images.portrait2],['“The shared records give our small team more time to focus on delivery.”','Grace N.','NGO programme coordinator',images.portrait3]].map(([q,n,r,img])=><article className="card quote" key={n}><p>{q}</p><div className="person"><Image src={img} alt="" width={44} height={44}/><span>{n}<small style={{display:'block',fontWeight:500,color:'var(--muted)'}}>{r}</small></span></div></article>)}</div><p className="muted" style={{fontSize:'.78rem',textAlign:'center',marginTop:15}}>Illustrative testimonials for this product preview.</p></div></section><section className="section"><div className="container card" style={{padding:'30px',display:'flex',flexWrap:'wrap',alignItems:'center',justifyContent:'space-between',gap:20}}><div><span className="eyebrow">Start with what you have</span><h2 className="heading" style={{fontSize:'clamp(1.7rem,3vw,2.3rem)',marginBottom:4}}>Make your next report a little easier.</h2><p className="muted" style={{margin:0}}>A free board gives your team room to get started.</p></div><Link className="btn" href="/register">Create a free board <ArrowRight size={18}/></Link></div></section></>}
function SamplePage({isPublic=false,org}:{isPublic?:boolean;org?:{name:string;county:string;blurb:string;visibleMetrics:string[];evidence?:{url:string;caption:string;date:string;contentType:string}[];summary:OrgReportData['summary'];chartData:OrgReportData['chartData']}}){const name=org?.name||'Tujenge Pamoja Community Programme';const blurb=org?.blurb||'Over the past year, community groups in Nakuru, Kiambu, Nairobi, and Machakos have worked together to strengthen household livelihoods and widen access to learning support. This sample page shows how recorded activities, participation, and programme spending can be presented clearly.';return <><PageTitle eyebrow={isPublic?'Community impact':'Public page preview'} title={isPublic?name:'A sample impact page'} text={isPublic?blurb:'A calm, printable example of the kind of programme update a team can share publicly.'}/><motion.main className="container content" initial={{opacity:0,y:12}} whileInView={{opacity:1,y:0}} viewport={{once:true}} transition={{duration:.45}}> <div className="card" style={{padding:22,marginBottom:22}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'start',gap:15,flexWrap:'wrap'}}><div><span className="eyebrow">{org?.county||'Nakuru, Kiambu, Nairobi and Machakos'}</span><h2 style={{margin:'8px 0 4px',letterSpacing:'-.035em'}}>{isPublic?'Programme reporting summary':'A year of steady community work'}</h2><p className="muted" style={{margin:0,maxWidth:850}}>{blurb}</p></div>{!isPublic&&<span className="pill"><Check size={14}/> Sample data</span>}</div></div><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,200px),1fr))',marginBottom:22}}>{(!isPublic||org?.visibleMetrics.includes('beneficiaries'))&&<KPI label="Beneficiaries reached" value={isPublic?new Intl.NumberFormat('en-KE').format(org?.summary.totalBeneficiaries||0):'5,420'} icon={Users}/>}{(!isPublic||org?.visibleMetrics.includes('counties'))&&<KPI label="Counties active" value={isPublic?String(org?.summary.counties||0):'4'} icon={Landmark}/>} {(!isPublic||org?.visibleMetrics.includes('activities'))&&<KPI label="Activities recorded" value={isPublic?String(org?.summary.activities||0):'54'} icon={Activity}/>} {(!isPublic||org?.visibleMetrics.includes('funds'))&&<KPI label="Funds deployed" value={isPublic?currency(org?.summary.fundsDeployed||0):'KES 1.78m'} icon={CircleDollarSign}/>}{isPublic&&org?.visibleMetrics.includes('volunteers')&&<KPI label="Active volunteers" value={String(org?.summary.activeVolunteers||0)} icon={HeartHandshake}/>}</div><ImpactCharts visible={isPublic?org?.visibleMetrics||[]:undefined} data={isPublic?org?.chartData:undefined}/>{isPublic&&org?.visibleMetrics.includes('evidence')&&org.evidence&&org.evidence.length>0&&<section style={{marginTop:22}}><h2>Shared programme evidence</h2><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,220px),1fr))'}}>{org.evidence.map((item,i)=><a className="card" key={`${item.url}-${i}`} href={item.url} target="_blank" rel="noreferrer" style={{padding:16}}><strong>{item.caption}</strong><div className="muted" style={{fontSize:'.8rem'}}>{item.contentType.includes('pdf')?'Open document':'Open photo'} · {new Date(item.date).toLocaleDateString('en-KE')}</div></a>)}</div></section>}<div className="card" style={{padding:22,marginTop:22}}><h2 style={{marginTop:0}}>What the figures describe</h2><p className="muted">{isPublic?`This organisation has recorded ${org?.summary.activities||0} activities and ${org?.summary.totalBeneficiaries||0} beneficiary records to date. Figures reflect the records supplied by the organisation and should be read alongside its context and evidence.`:`Programme teams recorded learning sessions, farmer group visits, community health outreach, and household support activities across four counties. These are illustrative sample figures for the page preview.`}</p><div style={{display:'flex',flexDirection:'column',gap:12}}><div className="notice">Figures are self-reported programme records, not an independent evaluation.</div><div className="notice">Barnabas Impact is a recording and reporting tool. It is not an auditor and does not provide assurance opinions.</div></div></div><div style={{display:'flex',gap:12,flexWrap:'wrap',marginTop:22}}><button className="btn" onClick={()=>downloadPdf(`${name} impact summary`,isPublic&&org?{summary:org.summary}:undefined)}><ArrowDownToLine size={18}/> Download PDF</button>{!isPublic&&<Link className="btn secondary" href="/register">Start your own board <ArrowRight size={18}/></Link>}{isPublic&&<button className="btn secondary" onClick={()=>navigator.clipboard?.writeText(window.location.href)}>Share page <FileText size={18}/></button>}</div></motion.main></>}
function PageTitle({eyebrow,title,text}:{eyebrow:string;title:string;text:string}){return <section className="page-head"><div className="container"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p className="muted" style={{maxWidth:780,margin:0}}>{text}</p></div></section>}
function ProductPage(){const items=[['Record people with care','Keep programme records useful and proportionate. Start with an anonymous ID, age band, county, programme, and date. Avoid collecting details you do not need.',images.meeting,'Beneficiary records'],['Make activities easy to revisit','Capture what happened, where it took place, and who it reached. A weekly routine gives your team more reliable numbers at reporting time.',images.field,'Activity log'],['Keep a plain finance summary','Record money in and out by category and project. See running totals while keeping your accounting system as the source for formal accounts.',images.garden,'Finance summary'],['Know who is supporting delivery','Keep volunteer availability, skills, and status in one roster. Phone details stay within the organisation workspace.',images.meeting,'Volunteer roster'],['Keep helpful evidence close','Upload a photo or document with a short caption and date. You choose whether any evidence is suitable for public sharing.',images.classroom,'Evidence locker'],['Publish only what you choose','Choose the metrics and short description that appear on the public page. Private beneficiary and volunteer details stay private.',images.field,'Public impact page']];return <><PageTitle eyebrow="Product" title="Reporting that fits a small team" text="Bring routine programme records together without adding a full data department or an extra layer of jargon."/><main className="container content">{items.map(([h,c,img,l],i)=><motion.section key={h} className="feature-row card" initial={{opacity:0,y:20}} whileInView={{opacity:1,y:0}} viewport={{once:true,amount:.2}}><div className="feature-image"><Image src={img} alt="Community programme setting" width={700} height={420} sizes="(max-width: 768px) 100vw, 50vw"/></div><div><span className="eyebrow">{l}</span><h2 style={{fontSize:'clamp(1.5rem,3vw,2.2rem)',lineHeight:1.2,letterSpacing:'-.04em'}}>{h}</h2><p className="muted">{c}</p><ul className="muted" style={{paddingLeft:19}}><li>Designed for a practical weekly reporting rhythm.</li><li>Keep organisation information in its own workspace.</li><li>Share selected summaries with clear context.</li></ul><Link href="/register" className="btn secondary small">Explore your board <ArrowRight size={16}/></Link></div></motion.section>)}<div className="notice">Barnabas Impact is a recording and reporting tool. It is not an auditor and does not provide assurance opinions.</div></main></>}
function PricingPage(){return <><PageTitle eyebrow="Straightforward plans" title="Start small. Grow as you need." text="Choose the plan that fits your programme today. Upgrade when your records, team, or reporting needs grow."/><main className="container content"><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,280px),1fr))'}}>{[{name:'Free',price:'KSh 0',feature:['1 project','Up to 100 beneficiary records','Basic reporting','PDF export']},{name:'Standard',price:'KSh 1,499',feature:['Multiple programme records','Public impact page','Reports and exports','Evidence uploads'],popular:true},{name:'Grant',price:'KSh 3,999',feature:['Multi-user team placeholder','Multiple programmes','Shared reporting workspace','Priority setup support']}].map(t=><article key={t.name} className="card" style={{padding:24,borderColor:t.popular?'var(--primary)':'var(--border)',borderWidth:t.popular?2:1}}>{t.popular&&<span className="pill">Most used</span>}<h2 style={{margin:'12px 0 4px'}}>{t.name}</h2><div style={{fontSize:'1.8rem',fontWeight:850,letterSpacing:'-.05em'}}>{t.price}<small style={{fontSize:'.85rem',fontWeight:500,color:'var(--muted)'}}>{t.name==='Free'?'':' / month'}</small></div><ul style={{paddingLeft:20,minHeight:145}}>{t.feature.map(f=><li key={f} style={{margin:'8px 0'}}>{f}</li>)}</ul><Link className={`btn ${t.popular?'':'secondary'}`} style={{width:'100%'}} href="/register">{t.name==='Free'?'Get started':'Choose '+t.name}</Link></article>)}</div><div className="table-wrap" style={{marginTop:35}}><table className="data-table"><thead><tr><th>Included</th><th>Free</th><th>Standard</th><th>Grant</th></tr></thead><tbody>{[['Projects','1','More','More'],['Beneficiary records','100','More','More'],['PDF reports','Included','Included','Included'],['Team members','1','1','Multi-user placeholder'],['Public page','Sample','Included','Included']].map(row=><tr key={row[0]}>{row.map((v,i)=><td key={i}>{v}</td>)}</tr>)}</tbody></table></div><p className="scroll-hint">Scroll sideways to compare plans</p></main></>}
function AboutPage(){return <><PageTitle eyebrow="About Barnabas Impact" title="Clear records. Honest reporting." text="We are building practical reporting tools for the people who keep community programmes moving."/><main className="container content"><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,320px),1fr))',alignItems:'start'}}><article className="card" style={{padding:26}}><span className="eyebrow">Our mission</span><h2>Make it easier to show the work.</h2><p className="muted">Small organisations are asked for useful evidence, clear numbers, and timely updates, often without a dedicated data team. Barnabas Impact helps bring records together so programme teams can spend less time rebuilding reports and more time supporting their communities.</p></article><article className="card" style={{padding:26}}><span className="eyebrow">Our accountability stance</span><h2>Clear about what the tool can do.</h2><p className="muted">We help record and present information. We do not validate the source records, independently evaluate programme outcomes, or issue audit opinions. Organisations remain responsible for accuracy, context, and careful sharing.</p><div className="notice">Barnabas Impact is a recording and reporting tool. It is not an auditor and does not provide assurance opinions.</div></article></div><section className="section" style={{paddingBottom:20}}><h2>People behind the work</h2><p className="muted">A small, Kenya-based product team working alongside programme coordinators and community organisations. Portraits shown here are illustrative Pexels photos, not staff identification.</p><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,230px),1fr))'}}>{[['Product and reporting','Nairobi'],['Community partnerships','Nakuru'],['Customer support','Across Kenya']].map(([a,b],i)=><article className="card" key={a} style={{padding:18}}><Image src={[images.portrait1,images.portrait2,images.portrait3][i]} alt="Team portrait" width={76} height={76} style={{borderRadius:'50%',objectFit:'cover'}}/><h3>{a}</h3><p className="muted" style={{margin:0}}>{b}</p></article>)}</div></section><div className="card" style={{padding:24}}><h3>Community partners</h3><p className="muted">We are grateful to the programme teams, community-based organisations, and local practitioners who share feedback as the product develops.</p><p style={{fontWeight:700}}>Partners are listed by name with permission.</p></div></main></>}
const legal:Record<string,{title:string;content:ReactNode}>={
 '/legal/privacy-policy':{title:'Privacy policy',content:<><h2>Our approach</h2><p>We design Barnabas Impact with Kenya's Data Protection Act, 2019 (KDPA) in mind. Organisations using the service decide what beneficiary information to collect and are responsible for having a lawful basis, providing notices, and handling that information responsibly.</p><h2>Beneficiary information</h2><p>Beneficiary records can be sensitive. Use anonymous identifiers and age bands where practical. Do not add details that are not needed for programme delivery or reporting. Dashboard records are scoped to the organisation using the board. Uploaded evidence uses Vercel Blob shareable URLs, so only upload material approved for public hosting. Public pages must not expose private volunteer phone numbers or beneficiary names.</p><h2>Retention, export, and erasure</h2><p>Organisations can request an export of their records and request erasure by contacting our support team. The organisation remains responsible for its retention schedule and any lawful preservation duties. We will explain the status of a request and relevant backup retention where applicable.</p><h2>Service providers</h2><p>We use infrastructure providers to host the service and, where enabled, Vercel Analytics to understand aggregate site performance. We do not place advertising pixels on dashboard paths or beneficiary-derived public pages. Programme data is never used to build advertising audiences.</p><h2>Security and contact</h2><p>We use access controls and organisation scoping as product safeguards. No online service can promise absolute security. For a data request or concern, contact us using the WhatsApp support link on this site.</p></>},
 '/legal/terms':{title:'Terms of use',content:<><h2>Using the service</h2><p>Barnabas Impact provides tools to record programme activities, beneficiaries, volunteer information, finance summaries, and evidence. You are responsible for the accuracy, completeness, and lawful collection of the information you enter, and for choosing what to publish.</p><h2>Not an audit or assurance service</h2><p>Barnabas Impact is a recording and reporting tool. It is not an auditor and does not provide assurance opinions. A report created with the service is not an independent verification, audit, or evaluation of programme outcomes.</p><h2>Privacy and account access</h2><p>Keep access credentials secure. Only invite people who need access. Your organisation is responsible for providing appropriate notices and safeguarding sensitive beneficiary information.</p><h2>Availability and changes</h2><p>We work to keep the service available and improve it over time. We may update product features or these terms, and will provide reasonable notice of material changes.</p></>},
 '/legal/cookie-policy':{title:'Cookie policy',content:<><h2>How storage is used</h2><p>Necessary storage keeps sign-in and security features working. Optional functional storage remembers preferences. Optional analytics may help us understand aggregate site use if you consent.</p><h2>Programme records are not advertising data</h2><p>Journal and beneficiary data are never used for advertising. We do not place third-party ad pixels on dashboard pages or beneficiary-derived public views. Vercel Analytics may be used for disclosed, aggregate site performance measurement with your choice.</p><h2>Manage your choice</h2><p>You can change optional cookie preferences using the banner when it appears. Necessary storage cannot be switched off because it supports core service functionality.</p></>}}
function LegalPage({path}:{path:string}){const item=legal[path];return <><PageTitle eyebrow="Legal" title={item.title} text="Last updated 27 October 2026. Plain-language notes about how the service works."/><main className="container content"><article className="card" style={{padding:'clamp(20px,5vw,40px)',maxWidth:900,margin:'0 auto'}}>{item.content}</article></main></>}
function AuthPage({register=false}:{register?:boolean}){
 const [message,setMessage]=useState(''); const [busy,setBusy]=useState(false); const [needV2,setNeedV2]=useState(false); const [v2Token,setV2Token]=useState(''); const router=useRouter(); const captchaWidget=useRef<number|null>(null)
 useEffect(()=>{if(!needV2||!process.env.NEXT_PUBLIC_RECAPTCHA_V2_SITE_KEY)return;const w=window as typeof window & {grecaptcha?:{render:(id:string,options:{sitekey:string;callback:(token:string)=>void})=>number}};let timer:number;const mount=()=>{if(w.grecaptcha&&captchaWidget.current===null){captchaWidget.current=w.grecaptcha.render('recaptcha-v2-container',{sitekey:process.env.NEXT_PUBLIC_RECAPTCHA_V2_SITE_KEY!,callback:(token)=>setV2Token(token)})}else if(!w.grecaptcha)timer=window.setTimeout(mount,150)};mount();return()=>window.clearTimeout(timer)},[needV2])
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMessage('');const data=Object.fromEntries(new FormData(e.currentTarget).entries());try{if(register){const res=await fetch('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,recaptchaToken:await recaptcha('register'),recaptchaV2Token:v2Token||undefined})});const body=await res.json();if(res.status===428&&body.needsV2){setNeedV2(true);setMessage(body.error||'Please complete the additional verification check.');return}if(!res.ok)throw new Error(body.error||'Registration could not be completed.');const result=await signIn('credentials',{email:data.email,password:data.password,redirect:false});if(result?.ok)router.push('/dashboard');else setMessage('Your account is ready. Sign in to continue.')}else{const result=await signIn('credentials',{email:data.email,password:data.password,redirect:false});if(result?.ok)router.push('/dashboard');else setMessage('Email or password was not recognised. Check your details and try again.')}}catch(err){setMessage(err instanceof Error?err.message:'Something went wrong.')}finally{setBusy(false)}}
 return <>{register&&process.env.NEXT_PUBLIC_RECAPTCHA_SITE_KEY&&<Script src={`https://www.google.com/recaptcha/api.js?render=${process.env.NEXT_PUBLIC_RECAPTCHA_SITE_KEY}`} strategy="afterInteractive"/>}<PageTitle eyebrow={register?'Create your board':'Your workspace'} title={register?'Set up your organisation board':'Welcome back. Let us continue the work.'} text={register?'A few details will get your first reporting board ready.':'Sign in to open your organisation workspace.'}/><main className="container content"><section className="card" style={{padding:'clamp(20px,5vw,36px)',maxWidth:650,margin:'0 auto'}}><form onSubmit={submit}><div className={`form-grid ${register?'two':''}`}>{register&&<><Field name="orgName" label="Organisation name" required/><Field name="contactName" label="Contact name" required/></>}<Field name="email" label="Email address" type="email" required/><Field name="password" label="Password" type="password" minLength={10} required/>{register&&<><label className="field">Organisation type<select name="orgType" required defaultValue=""><option value="" disabled>Select organisation type</option>{['CBO','NGO','Faith-based','School programme','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label className="field">County<select name="county" required defaultValue=""><option value="" disabled>Select county</option>{counties.map(c=><option key={c}>{c}</option>)}</select></label></>}</div>{register&&<p className="muted" style={{fontSize:'.8rem'}}>This form uses invisible reCAPTCHA v3. A low verification score will ask for an additional checkbox challenge.</p>}{needV2&&<div style={{marginTop:14}}><div id="recaptcha-v2-container" aria-label="Additional verification challenge"/>{!process.env.NEXT_PUBLIC_RECAPTCHA_V2_SITE_KEY&&<p className="notice">Additional verification needs NEXT_PUBLIC_RECAPTCHA_V2_SITE_KEY configured by the site administrator.</p>}{v2Token&&<span className="pill"><Check size={14}/> Verification complete</span>}</div>}{message&&<div className="notice" role="status" style={{marginTop:15}}>{message}</div>}<button className="btn" style={{width:'100%',marginTop:18}} disabled={busy}>{busy?(register?'Creating board...':'Signing in...'):(register?'Create my board':'Sign in')}</button><div style={{display:'flex',alignItems:'center',gap:12,margin:'18px 0',color:'var(--muted)',fontSize:'.82rem'}}><span style={{height:1,background:'var(--border)',flex:1}}/>or continue with Google<span style={{height:1,background:'var(--border)',flex:1}}/></div><button type="button" className="btn secondary" style={{width:'100%'}} onClick={()=>signIn('google',{callbackUrl:'/dashboard'})}>Continue with Google</button><p className="muted" style={{textAlign:'center',fontSize:'.86rem'}}>{register?'Already have a board? ':'New to Barnabas Impact? '}<Link href={register?'/login':'/register'} style={{color:'var(--primary-dark)',fontWeight:800}}>{register?'Sign in':'Create a board'}</Link></p></form></section></main></>
}
function Field({name,label,type='text',required=false,minLength,onChange}:{name:string;label:string;type?:string;required?:boolean;minLength?:number;onChange?:(event:ChangeEvent<HTMLInputElement>)=>void}){return <label className="field">{label}<input name={name} type={type} required={required} minLength={minLength} onChange={onChange} autoComplete={type==='password'?'new-password':name==='email'?'email':'on'}/></label>}
async function recaptcha(action:string){const siteKey=process.env.NEXT_PUBLIC_RECAPTCHA_SITE_KEY;if(!siteKey)return '';const w=window as typeof window & {grecaptcha?:{ready:(cb:()=>void)=>void;execute:(key:string,opts:{action:string})=>Promise<string>;render:(id:string,options:{sitekey:string;callback:(token:string)=>void})=>number}};if(!w.grecaptcha)return '';return new Promise<string>(resolve=>w.grecaptcha!.ready(()=>{w.grecaptcha!.execute(siteKey,{action}).then(resolve).catch(()=>resolve(''))}))}
function inReportRange(row:{date?:unknown;createdAt?:unknown},range:string,start:string,end:string){const raw=String(row.date||row.createdAt||'');const date=new Date(raw);if(Number.isNaN(date.getTime()))return false;const now=new Date();let from:Date;let to=new Date(now);if(range==='This month')from=new Date(now.getFullYear(),now.getMonth(),1);else if(range==='Last quarter'){const quarter=Math.floor(now.getMonth()/3)*3;from=new Date(now.getFullYear(),quarter-3,1);to=new Date(now.getFullYear(),quarter,1);to.setMilliseconds(to.getMilliseconds()-1)}else if(range==='Last 12 months')from=new Date(now.getFullYear(),now.getMonth()-11,1);else{from=start?new Date(`${start}T00:00:00`):new Date(0);to=end?new Date(`${end}T23:59:59`):new Date()}return date>=from&&date<=to}
const counties=['Baringo','Bomet','Bungoma','Busia','Elgeyo-Marakwet','Embu','Garissa','Homa Bay','Isiolo','Kajiado','Kakamega','Kericho','Kiambu','Kilifi','Kirinyaga','Kisii','Kisumu','Kitui','Kwale','Laikipia','Lamu','Machakos','Makueni','Mandera','Marsabit','Meru','Migori','Mombasa','Murang’a','Nairobi','Nakuru','Nandi','Narok','Nyamira','Nyandarua','Nyeri','Samburu','Siaya','Taita-Taveta','Tana River','Tharaka-Nithi','Trans Nzoia','Turkana','Uasin Gishu','Vihiga','Wajir','West Pokot']
function DashNav({path}:{path:string}){return <><aside className="sidebar"><div className="eyebrow" style={{padding:'10px 11px 14px'}}>Organisation workspace</div><nav className="dash-nav">{navItems.map((item,index)=><motion.div key={item.href} initial={{opacity:0}} animate={{opacity:1}} transition={{duration:.22,delay:index*.025}}><Link href={item.href} className={`dash-link ${path===item.href?'active':''}`}><item.icon size={18}/>{item.label}</Link></motion.div>)}</nav><div style={{marginTop:'auto',padding:'14px 10px'}}><div className="notice" style={{fontSize:'.78rem'}}>Keep sensitive records in your organisation workspace.</div></div></aside><nav className="mobile-tabs" aria-label="Dashboard tabs">{[{...navItems[0],label:'Home'},{...navItems[1],label:'People'},{...navItems[2],label:'Activities'},{...navItems[3],label:'Finance'},{href:'/dashboard/reports',label:'More',icon:Menu}].map(item=><Link key={item.href} href={item.href} className={path===item.href?'active':''}><item.icon size={19}/><span>{item.label}</span></Link>)}</nav></>}
function Dashboard({path,data}:{path:string;data:OrgReportData}){
 const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [publicSlug,setPublicSlug]=useState('tujenge-pamoja');const [reportPeriod,setReportPeriod]=useState('This month');const [customStart,setCustomStart]=useState('');const [customEnd,setCustomEnd]=useState('');const numbers=useRef<HTMLDivElement>(null);const router=useRouter()
 useEffect(()=>{if(numbers.current)gsap.fromTo(numbers.current.querySelectorAll('[data-count]'),{innerText:0},{innerText:(i:number,target:HTMLElement)=>Number(target.dataset.count),duration:1.15,snap:{innerText:1},stagger:.12,ease:'power1.out'})},[])
 const section=path.split('/').pop()||'dashboard'
 const reportBeneficiaries=data.beneficiaries.filter(row=>inReportRange(row,reportPeriod,customStart,customEnd))
 const reportActivities=data.activities.filter(row=>inReportRange(row,reportPeriod,customStart,customEnd))
 const reportFinance=data.finance.filter(row=>inReportRange(row,reportPeriod,customStart,customEnd))
 const reportSummary={beneficiariesMTD:reportBeneficiaries.length,totalBeneficiaries:reportBeneficiaries.length,activities:reportActivities.length,fundsDeployed:reportFinance.filter(row=>row.type==='Out').reduce((sum,row)=>sum+Number(row.amount||0),0),activeVolunteers:data.summary.activeVolunteers,counties:new Set([...reportBeneficiaries.map(row=>String(row.county||'')),...reportActivities.map(row=>String(row.county||''))].filter(Boolean)).size}
 const reportChartData:OrgReportData['chartData']={months:Array.from({length:12},(_,i)=>{const d=new Date(new Date().getFullYear(),new Date().getMonth()-(11-i),1);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return{month:d.toLocaleString('en-KE',{month:'short'}),beneficiaries:reportBeneficiaries.filter(row=>String(row.date||row.createdAt||'').startsWith(key)).length}}),programs:[...reportActivities.reduce((map,row)=>{const key=String(row.program||'Other');map.set(key,(map.get(key)||0)+1);return map},new Map<string,number>())].map(([program,activities])=>({program,activities})),funds:[...reportFinance.filter(row=>row.type==='Out').reduce((map,row)=>{const key=String(row.category||'Other');map.set(key,(map.get(key)||0)+Number(row.amount||0));return map},new Map<string,number>())].map(([category,amount])=>({category,amount}))}
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMessage('');const form=e.currentTarget;const formData=new FormData(form);try{let response:Response;if(section==='evidence'){response=await fetch('/api/evidence/upload',{method:'POST',body:formData})}else if(section==='activities'&&formData.get('photo') instanceof File&&(formData.get('photo') as File).size>0){response=await fetch('/api/activities/add',{method:'POST',body:formData})}else{const body:Record<string, unknown>=Object.fromEntries(formData.entries());if(section==='beneficiaries')body.anonymous=formData.get('anonymous')==='on';response=await fetch(`/api/${section==='beneficiaries'?'beneficiaries':section==='activities'?'activities':section==='finance'?'finance':'volunteers'}/add`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save.');setMessage('Saved to your organisation workspace.');form.reset();router.refresh()}catch(err){setMessage(err instanceof Error?err.message:'Could not save. Please try again.')}finally{setBusy(false)}}
 async function publish(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);const body={published:form.get('published')==='on',slug:String(form.get('slug')),blurb:String(form.get('blurb')),visibleMetrics:form.getAll('visibleMetrics')};const res=await fetch('/api/public/publish',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await res.json();setMessage(res.ok?`Settings saved. Your public page is ${body.published?'published':'unpublished'}.`:data.error||'Could not save settings.');if(res.ok)router.refresh()}
 const titles:Record<string,string>={dashboard:'Overview',beneficiaries:'Beneficiaries',activities:'Activities',finance:'Finance',volunteers:'Volunteers',evidence:'Evidence locker',reports:'Reports', 'public-page':'Public page'}
 return <><Header/><div className="dashboard-shell"><DashNav path={path}/><main className="dash-main"><div style={{display:'flex',justifyContent:'space-between',alignItems:'start',gap:14,flexWrap:'wrap',marginBottom:24}}><div><span className="eyebrow">Barnabas Impact / Workspace</span><h1 style={{fontSize:'clamp(1.8rem,4vw,2.6rem)',letterSpacing:'-.05em',margin:'4px 0'}}>{titles[section]||'Overview'}</h1><p className="muted" style={{margin:0}}>Your organisation · Reporting board</p></div><button className="btn secondary small" onClick={()=>signOut({callbackUrl:'/'})}>Sign out</button></div>
 {section==='dashboard'&&<><div className="grid" ref={numbers} style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,180px),1fr))',marginBottom:22}}><div className="kpi"><div className="kpi-label">Beneficiaries MTD</div><div className="kpi-value" data-count={data.summary.beneficiariesMTD}>0</div></div><div className="kpi"><div className="kpi-label">Activities logged</div><div className="kpi-value" data-count={data.summary.activities}>0</div></div><div className="kpi"><div className="kpi-label">Funds deployed</div><div className="kpi-value">KES <span data-count={data.summary.fundsDeployed}>0</span></div></div><div className="kpi"><div className="kpi-label">Active volunteers</div><div className="kpi-value" data-count={data.summary.activeVolunteers}>0</div></div></div><ImpactCharts data={data.chartData}/>{data.activities.length===0&&<div className="notice" style={{marginTop:16}}>No activity has been recorded yet. Your dashboard will reflect your organisation's records as you add them.</div>}<div className="card" style={{padding:20,marginTop:22}}><h2 style={{fontSize:'1.08rem',marginTop:0}}>Recent activity</h2>{data.activities.slice(0,5).map((row,i)=><div key={`${row.createdAt||row.date}-${i}`} style={{display:'flex',gap:16,padding:'13px 0',borderTop:'1px solid var(--border)'}}><span className="muted" style={{minWidth:76,fontSize:'.8rem'}}>{String(row.date||row.createdAt||'').slice(0,10)||'Date not set'}</span><div><strong>{String(row.title||'Activity record')}</strong><div className="muted" style={{fontSize:'.82rem'}}>{String(row.program||'Programme not set')} · {String(row.beneficiariesReached||0)} people reached</div></div></div>)}{data.activities.length===0&&<p className="muted" style={{margin:0}}>Your latest entries will appear here.</p>}</div></>}
 {section==='beneficiaries'&&<><section className="card" style={{padding:20,marginBottom:22}}><h2 style={{marginTop:0}}>Add a beneficiary record</h2><form onSubmit={submit}><div className="form-grid two"><Field name="idCode" label="Record ID code" required/><label className="field">Age band<select name="ageBand" required defaultValue=""><option value="" disabled>Select age band</option>{['0–5','6–12','13–17','18–24','25–34','35–49','50–64','65+'].map(x=><option key={x}>{x}</option>)}</select></label><label className="field">Gender<select name="gender" required defaultValue=""><option value="" disabled>Select</option>{['Female','Male','Non-binary','Prefer not to say','Not recorded'].map(x=><option key={x}>{x}</option>)}</select></label><label className="field">County<select name="county" required defaultValue=""><option value="" disabled>Select county</option>{counties.map(c=><option key={c}>{c}</option>)}</select></label><Field name="program" label="Programme" required/><Field name="date" label="Date" type="date" required/></div><label style={{display:'flex',gap:9,alignItems:'center',marginTop:14}}><input type="checkbox" name="anonymous" defaultChecked/>Use anonymous mode (recommended)</label><div className="form-actions"><button className="btn" disabled={busy}><Plus size={17}/>{busy?'Saving...':'Add beneficiary'}</button></div></form>{message&&<div className="notice" style={{marginTop:12}}>{message}</div>}</section><DataTable title="Recent beneficiary records" headings={['ID code','Age band','Gender','County','Programme','Date']} rows={data.beneficiaries.map(row=>[String(row.idCode||'Anonymous record'),String(row.ageBand||'Not recorded'),String(row.gender||'Not recorded'),String(row.county||''),String(row.program||''),String(row.date||'')])}/></>}
 {section==='activities'&&<><section className="card" style={{padding:20,marginBottom:22}}><h2 style={{marginTop:0}}>Log an activity</h2><form onSubmit={submit}><div className="form-grid two"><Field name="title" label="Activity title" required/><Field name="program" label="Programme area" required/><Field name="date" label="Date" type="date" required/><label className="field">County<select name="county" required defaultValue=""><option value="" disabled>Select county</option>{counties.map(c=><option key={c}>{c}</option>)}</select></label><Field name="beneficiariesReached" label="Beneficiaries reached" type="number" required/><label className="field">Location<input name="location" placeholder="Community or venue"/></label><label className="field" style={{gridColumn:'1/-1'}}>Notes<textarea name="notes"/></label><label className="field">Optional photo<input name="photo" type="file" accept="image/*"/></label></div><div className="form-actions"><button className="btn" disabled={busy}><Plus size={17}/>{busy?'Saving...':'Save activity'}</button></div></form>{message&&<div className="notice" style={{marginTop:12}}>{message}</div>}</section><DataTable title="Recent activities" headings={['Activity','Programme','Date','Location','People reached']} rows={data.activities.map(row=>[String(row.title||'Activity'),String(row.program||''),String(row.date||''),String(row.location||row.county||''),String(row.beneficiariesReached||0)])}/></>}
 {section==='finance'&&<><section className="card" style={{padding:20,marginBottom:22}}><h2 style={{marginTop:0}}>Add a ledger entry</h2><form onSubmit={submit}><div className="form-grid two"><Field name="date" label="Date" type="date" required/><label className="field">Type<select name="type"><option>In</option><option>Out</option></select></label><Field name="category" label="Category" required/><Field name="amount" label="Amount (KES)" type="number" required/><Field name="project" label="Project tag"/><label className="field" style={{gridColumn:'1/-1'}}>Notes<textarea name="notes"/></label></div><div className="form-actions"><button className="btn" disabled={busy}><Plus size={17}/>{busy?'Saving...':'Add entry'}</button></div></form>{message&&<div className="notice" style={{marginTop:12}}>{message}</div>}</section><div className="notice" style={{marginBottom:16}}>This is a simple programme ledger summary, not full accounting software. Keep your official books and source documents.</div><div className="grid" style={{gridTemplateColumns:'repeat(auto-fit,minmax(min(100%,200px),1fr))',marginBottom:18}}><KPI label="Money in" value={currency(data.finance.filter(row=>row.type==='In').reduce((sum,row)=>sum+Number(row.amount||0),0))} icon={ArrowDownToLine}/><KPI label="Money out" value={currency(data.summary.fundsDeployed)} icon={CircleDollarSign}/><KPI label="Balance" value={currency(data.finance.reduce((sum,row)=>sum+(row.type==='In'?Number(row.amount||0):-Number(row.amount||0)),0))} icon={Landmark}/></div><DataTable title="Recent ledger entries" headings={['Date','Type','Category','Amount','Project','Notes']} rows={data.finance.map(row=>[String(row.date||''),String(row.type||''),String(row.category||''),currency(Number(row.amount||0)),String(row.project||''),String(row.notes||'')])}/></>}
 {section==='volunteers'&&<><section className="card" style={{padding:20,marginBottom:22}}><h2 style={{marginTop:0}}>Add a volunteer</h2><form onSubmit={submit}><div className="form-grid two"><Field name="name" label="Name" required/><Field name="phone" label="Phone" type="tel" required/><Field name="skills" label="Skills"/><label className="field">Status<select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label></div><div className="form-actions"><button className="btn" disabled={busy}><Plus size={17}/>{busy?'Saving...':'Add volunteer'}</button></div></form>{message&&<div className="notice" style={{marginTop:12}}>{message}</div>}</section><DataTable title="Volunteer roster" headings={['Name','Phone','Skills','Status']} rows={data.volunteers.map(row=>[String(row.name||''),String(row.phone||''),String(row.skills||''),String(row.status||'')])}/></>}
 {section==='evidence'&&<><section className="card" style={{padding:20,marginBottom:22}}><h2 style={{marginTop:0}}>Add a file to your evidence locker</h2><form onSubmit={submit} encType="multipart/form-data"><div className="form-grid two"><label className="field">Photo or PDF<input name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required/></label><Field name="caption" label="Caption"/></div><p className="muted" style={{fontSize:'.8rem'}}>JPG, PNG, WEBP, or PDF, up to 10 MB. Files use shareable Blob URLs, so only upload material approved for public hosting. The public page will not highlight them unless you opt in.</p><div className="form-actions"><button className="btn" disabled={busy}><Plus size={17}/>{busy?'Uploading...':'Upload evidence'}</button></div></form>{message&&<div className="notice" style={{marginTop:12}}>{message}</div>}</section><div className="grid" style={{gridTemplateColumns:'repeat(2,minmax(0,1fr))'}}>{data.evidence.map((row,i)=><a className="card" key={`${row.createdAt||row.url}-${i}`} href={String(row.url||'#')} target="_blank" rel="noreferrer" style={{padding:16}}><div className="iconbox"><FileText size={20}/></div><strong style={{display:'block',marginTop:12}}>{String(row.caption||row.fileName||'Evidence file')}</strong><div className="muted" style={{fontSize:'.78rem'}}>{String(row.createdAt||'Date not recorded').slice(0,10)}</div></a>)}</div>{data.evidence.length===0&&<p className="muted">No files are uploaded yet. Add a photo or document above to get started.</p>}</>}
 {section==='reports'&&<><div className="card" style={{padding:20,marginBottom:20}}><h2 style={{marginTop:0}}>Build a report</h2><div className="form-grid two"><label className="field">Date range<select value={reportPeriod} onChange={event=>setReportPeriod(event.target.value)}><option>This month</option><option>Last quarter</option><option>Last 12 months</option><option>Custom</option></select></label>{reportPeriod==='Custom'&&<><Field name="custom-start" label="From" type="date" onChange={event=>setCustomStart(event.target.value)}/><Field name="custom-end" label="To" type="date" onChange={event=>setCustomEnd(event.target.value)}/></> }<label className="field">Programme<select><option>All programmes</option><option>Livelihoods</option><option>Education</option><option>Health</option></select></label></div><div className="form-actions"><button className="btn secondary" onClick={()=>{const csv=`Metric,Value\nBeneficiary records,${reportSummary.totalBeneficiaries}\nActivities logged,${reportSummary.activities}\nFunds deployed,KES ${reportSummary.fundsDeployed}\nActive volunteers,${reportSummary.activeVolunteers}`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='barnabas-impact-summary.csv';a.click()}}>Export CSV</button><button className="btn" onClick={()=>downloadPdf('Programme report', {summary:reportSummary})}><ArrowDownToLine size={17}/> Export PDF</button></div></div><div className="grid" style={{gap:12,marginBottom:20}}>{[`You logged ${reportActivities.filter(row=>row.county==='Nairobi').length} activities in Nairobi County for this reporting period.`,`Your records show ${reportSummary.totalBeneficiaries} beneficiary records for the selected reporting period.`,`The programme ledger records ${currency(reportSummary.fundsDeployed)} in recorded spending for the selected period.`].map((x,i)=><motion.div key={x} className="notice" initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*.15}}>{x}</motion.div>)}</div><ImpactCharts compact data={reportChartData}/></>}
 {section==='public-page'&&<><section className="card" style={{padding:20,maxWidth:820}}><h2 style={{marginTop:0}}>Choose what your public page shares</h2><form onSubmit={publish}><label style={{display:'flex',gap:10,alignItems:'center',marginBottom:16}}><input name="published" type="checkbox" defaultChecked/>Publish this page</label><div className="form-grid"><label className="field">Public page slug<input name="slug" value={publicSlug} onChange={event=>setPublicSlug(event.target.value)} required/></label><label className="field">Short introduction<textarea name="blurb" defaultValue="Our community programme works with local groups to strengthen livelihoods and widen learning support across our county."/></label></div><p style={{fontWeight:800,marginBottom:8}}>Visible metrics</p>{['beneficiaries','activities','funds','volunteers','evidence','counties'].map(x=><label key={x} style={{display:'inline-flex',gap:7,alignItems:'center',marginRight:16,marginBottom:12,textTransform:'capitalize'}}><input type="checkbox" name="visibleMetrics" value={x} defaultChecked={x!=='volunteers'}/>{x}</label>)}<div className="form-actions"><button className="btn">Save public page settings</button></div></form>{message&&<div className="notice" style={{marginTop:14}}>{message}</div>}<p style={{marginTop:18}}>Preview: <Link href={`/p/${publicSlug}`} style={{color:'var(--primary-dark)',fontWeight:800}}>/p/{publicSlug} <ArrowRight size={14} style={{verticalAlign:'middle'}}/></Link></p></section></>}
 </main></div></>
}
function DataTable({title,headings,rows}:{title:string;headings:string[];rows:string[][]}){return <section className="card" style={{padding:'18px 0'}}><h2 style={{fontSize:'1.08rem',padding:'0 18px',margin:'0 0 14px'}}>{title}</h2><div className="table-wrap"><table className="data-table"><thead><tr>{headings.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length?rows.map((r,i)=><tr key={i}>{r.map((x,j)=><td key={j}>{x}</td>)}</tr>):<tr><td colSpan={headings.length} style={{textAlign:'center',color:'var(--muted)',padding:28}}>No records yet. Add your first entry above.</td></tr>}</tbody></table></div><p className="scroll-hint">Scroll sideways to view all columns</p></section>}
function ErrorPage({code}:{code:'404'|'500'}){return <main className="container" style={{padding:'88px 16px',textAlign:'center'}}><span className="eyebrow">Barnabas Impact · {code}</span><h1 className="heading" style={{fontSize:'clamp(2.4rem,7vw,4rem)'}}>{code==='404'?'This page is not here.':'We could not load this page.'}</h1><p className="muted" style={{maxWidth:560,margin:'0 auto 22px'}}>{code==='404'?'The link may have changed, but your next step is easy. Return to the homepage or explore a sample report.':'Your work matters. Please try again or message our support team.'}</p><div className="hero-actions" style={{justifyContent:'center'}}><Link className="btn" href="/">Go to homepage</Link>{code==='404'?<Link className="btn secondary" href="/sample">View sample report</Link>:<a className="btn secondary" href="https://wa.me/254112272061">WhatsApp +254112272061</a>}</div></main>}
export default function Site({path,publicOrg,dashboardData}:{path:string;dashboardData?:OrgReportData;publicOrg?:{name:string;county:string;blurb:string;visibleMetrics:string[];evidence?:{url:string;caption:string;date:string;contentType:string}[];summary:OrgReportData['summary'];chartData:OrgReportData['chartData']}}){const isDashboard=path==='/dashboard'||path.startsWith('/dashboard/');const isPublic=path.startsWith('/p/');let body:ReactNode
 if(isDashboard) return <Dashboard path={path} data={dashboardData!}/>
 if(path==='/')body=<HomePage/>;else if(path==='/product')body=<ProductPage/>;else if(path==='/sample')body=<SamplePage/>;else if(path==='/pricing')body=<PricingPage/>;else if(path==='/about')body=<AboutPage/>;else if(path==='/login')body=<AuthPage/>;else if(path==='/register')body=<AuthPage register/>;else if(path in legal)body=<LegalPage path={path}/>;else if(path==='/404')body=<ErrorPage code="404"/>;else if(path==='/500')body=<ErrorPage code="500"/>;else if(isPublic)body=<SamplePage isPublic org={publicOrg}/>;else body=<ErrorPage code="404"/>
 return <><Header/>{body}<Footer/></>
}
